import { TestBed } from '@angular/core/testing';
import { provideHttpClient } from '@angular/common/http';
import { provideHttpClientTesting, HttpTestingController } from '@angular/common/http/testing';
import { TranslateModule } from '@ngx-translate/core';
import { UserStore } from './user.store';
import { ConfigStore } from './config.store';
import { UserService } from '../services/user.service';
import { describe, it, expect, beforeEach, afterEach } from 'vitest';

describe('UserStore', () => {
  let store: InstanceType<typeof UserStore>;
  let httpMock: HttpTestingController;

  beforeEach(() => {
    TestBed.configureTestingModule({
      imports: [
        TranslateModule.forRoot()
      ],
      providers: [
        UserStore,
        ConfigStore,
        UserService,
        provideHttpClient(),
        provideHttpClientTesting()
      ]
    });

    httpMock = TestBed.inject(HttpTestingController);
    store = TestBed.inject(UserStore);

    // Call initial checkStatus() manually as we removed onInit hook
    store.checkStatus();
    const req = httpMock.expectOne('https://dev.api.citizenos.com:3003/api/auth/status');
    req.flush({ data: null });
  });

  afterEach(() => {
    httpMock.verify();
  });

  it('should initialize with default state', () => {
    expect(store.user()).toBeNull();
    expect(store.isAuthenticated()).toBeFalsy();
    expect(store.isLoading()).toBeFalsy();
  });

  it('should call loginSmartIdInit and update loading state', async () => {
    const promise = store.loginSmartIdInit('12345678901');

    const req = httpMock.expectOne('https://dev.api.citizenos.com:3003/api/auth/smartid/init');
    expect(store.isLoading()).toBeTruthy();

    req.flush({ data: { challengeID: 1234, token: 'tok' } });
    const res = await promise as any;

    expect(res.challengeID).toBe(1234);
    expect(store.isLoading()).toBeFalsy();
  });

  it('should call loginSmartIdStatus', async () => {
    const promise = store.loginSmartIdStatus('tok');

    const req = httpMock.expectOne((r) => r.url.endsWith('/api/auth/smartid/status') && r.params.get('token') === 'tok');
    req.flush({ status: { code: 20001 } });

    const res = await promise as any;
    expect(res.status.code).toBe(20001);
  });

  it('should call loginMobiilIdInit and update loading state', async () => {
    const promise = store.loginMobiilIdInit('12345678901', '+372555');

    const req = httpMock.expectOne((r) => r.url.endsWith('/api/auth/mobile/init'));
    expect(store.isLoading()).toBeTruthy();

    req.flush({ data: { challengeID: 1234, token: 'tok' } });
    const res = await promise as any;

    expect(res.challengeID).toBe(1234);
    expect(store.isLoading()).toBeFalsy();
  });

  it('should call loginMobiilIdStatus', async () => {
    const promise = store.loginMobiilIdStatus('tok');

    const req = httpMock.expectOne((r) => r.url.endsWith('/api/auth/mobile/status') && r.params.get('token') === 'tok');
    req.flush({ status: { code: 20001 } });

    const res = await promise as any;
    expect(res.status.code).toBe(20001);
  });

  it('should call loginIdCard', async () => {
    const authResponse = { response: 'test' };
    const promise = store.loginIdCard(authResponse);

    const req = httpMock.expectOne((r) => r.url.endsWith('/api/auth/id'));
    expect(req.request.method).toBe('POST');
    expect(req.request.body).toEqual(authResponse);

    req.flush({ status: { code: 200 } });

    await new Promise(resolve => setTimeout(resolve, 0)); // Wait for second request to be triggered

    const statusReq = httpMock.expectOne((r) => r.url.includes('/api/auth/status'));
    statusReq.flush({ data: null });

    await promise;
  });
});

import { ComponentFixture, TestBed } from '@angular/core/testing';
import { LoginComponent } from './login.component';
import { ReactiveFormsModule } from '@angular/forms';
import { Router } from '@angular/router';
import { TranslateModule } from '@ngx-translate/core';
import { UserStore } from '../../../core/state/user.store';
import { UserService } from '../../../core/services/user.service';

import { signal, NO_ERRORS_SCHEMA } from '@angular/core';
import { describe, it, expect, beforeEach, vi, Mock } from 'vitest';
import { provideRouter } from '@angular/router';

describe('LoginComponent', () => {
  let component: LoginComponent;
  let fixture: ComponentFixture<LoginComponent>;
  let mockUserStore: unknown;
  let mockUserService: unknown;

  beforeEach(async () => {
    mockUserStore = {
      login: vi.fn(),
      isLoading: signal(false)
    };
    mockUserService = {
      getPartnerLoginUrl: vi.fn().mockReturnValue('http://partner-login.url')
    };
    await TestBed.configureTestingModule({
      imports: [LoginComponent, ReactiveFormsModule, TranslateModule.forRoot()],
      providers: [
        provideRouter([]),
        { provide: UserStore, useValue: mockUserStore },
        { provide: UserService, useValue: mockUserService }
      ],
      schemas: [NO_ERRORS_SCHEMA]
    }).compileComponents();

    fixture = TestBed.createComponent(LoginComponent);
    component = fixture.componentInstance;
    fixture.detectChanges();
  });

  it('should create', () => {
    expect(component).toBeTruthy();
  });

  it('should have an invalid form when empty', () => {
    expect(component.loginForm().invalid()).toBeTruthy();
  });

  it('should validate email format', () => {
    component.loginModel.update(m => ({ ...m, email: 'invalid-email' }));
    fixture.detectChanges();
    TestBed.flushEffects();
    expect(component.loginForm.email().errors().some(e => e.kind === 'email')).toBeTruthy();

    component.loginModel.update(m => ({ ...m, email: 'test@example.com' }));
    fixture.detectChanges();
    TestBed.flushEffects();
    expect(component.loginForm.email().errors().some(e => e.kind === 'email')).toBeFalsy();
  });

  it('should toggle password visibility', () => {
    expect(component.showPassword()).toBeFalsy();
    component.togglePassword();
    expect(component.showPassword()).toBeTruthy();
  });

  it('should call login on UserStore when form is submitted', async () => {
    const router = TestBed.inject(Router);
    const navigateSpy = vi.spyOn(router, 'navigate');
    component.loginModel.set({
      email: 'test@example.com',
      password: 'password123'
    });
    fixture.detectChanges();
    TestBed.flushEffects();

    (mockUserStore as { login: Mock }).login.mockResolvedValue({});

    await component.save(component.loginModel());

    expect((mockUserStore as { login: Mock }).login).toHaveBeenCalledWith('test@example.com', 'password123');
    expect(navigateSpy).toHaveBeenCalledWith(['/']);
  });

  it('should handle login error', async () => {
    component.loginModel.set({
      email: 'test@example.com',
      password: 'wrong-password'
    });
    fixture.detectChanges();
    TestBed.flushEffects();

    (mockUserStore as { login: Mock }).login.mockRejectedValue(new Error('Login failed'));

    await component.save(component.loginModel());

    expect(component.error()).toBe('Login failed. Please check your credentials.');
  });

  it('should navigate to partner login URL', () => {
    // We can't easily test window.location.href changes in unit tests
    // but we can test that the service is called.
    const originalLocation = window.location;
    vi.stubGlobal('location', { ...originalLocation, href: '' });

    component.doLoginPartner('google');

    expect((mockUserService as any).getPartnerLoginUrl).toHaveBeenCalledWith('google', undefined);
    expect(window.location.href).toBe('http://partner-login.url');

    vi.unstubAllGlobals();
  });
});

