export class ListFilterToolbarComponent {
  filters = model<FilterConfig[]>([]);
  filtersExtra = model<FilterConfig[]>([]);
  searchPlaceholder = input<string>('');
  searchValue = model<string>('');
  filterChange = output<{ key: string, value: string }>();
  searchChange = output<string>();

  moreFilters = signal(false);
  mobileFiltersOpen = signal(false);
  activeMobileFilter = signal<string | null>(null);

  allFilters = computed(() => {
    return [...this.filters(), ...this.filtersExtra().map(f => ({...f, type: 'filter'}))] as FilterConfig[];
  });

  constructor() {
    effect(() => this.searchChange.emit(this.searchValue()));
  }

  mainRows = computed(() => {
    const f = this.filters();
    const chunks = [];
    for (let i = 0; i < f.length; i += 4) {
      chunks.push(f.slice(i, i + 4));
    }
    return chunks;
  });

  extraRows = computed(() => {
    const ex = this.filtersExtra();
    const items: (FilterConfig & { type: string } | { type: string })[] = [
      ...ex.map(f => ({ ...f, type: 'filter' })),
      { type: 'search' }
    ];
    const chunks = [];
    for (let i = 0; i < items.length; i += 4) {
      chunks.push(items.slice(i, i + 4));
    }
    return chunks;
  });

  hasActiveFilters = computed(() => {
    const filterActive = [...this.filters(), ...this.filtersExtra()].some(f => f.selectedValue !== '' && f.selectedValue !== 'all');
    return filterActive || this.searchValue() !== '';
  });

  getActiveFilterText(filter: FilterConfig): string {
    const value = filter.selectedValue === '' ? 'all' : filter.selectedValue;
    return filter.items.find(item => item.value === value)?.title || filter.placeholder;
  }

  getActiveFilter(key: string): FilterConfig | undefined {
    return this.allFilters().find(f => f.key === key);
  }

  selectFilter(key: string, value: string) {
    this.filterChange.emit({ key, value });
  }

  clearAll() {
    [...this.filters(), ...this.filtersExtra()].forEach(f => this.filterChange.emit({ key: f.key, value: 'all' }));
    this.searchValue.set('');
  }
}

import { Component, input, model, output, computed, ChangeDetectionStrategy } from '@angular/core';

@Component({
  changeDetection: ChangeDetectionStrategy.OnPush,
  selector: 'cos-toggle',
  standalone: true,
  imports: [],
  templateUrl: './toggle.component.html',
  styleUrls: ['./toggle.component.scss']
})
export class ToggleComponent {
  /**
   * modelValue supports 2-way binding via [(model)].
   * Uses 'any' to ensure compatibility with various types (boolean, string, etc.) 
   * in Angular templates without requiring explicit casting.
   */
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  modelValue = model<any>(false, { alias: 'model' });

  /**
   * The value that represents the 'ON' state.
   */
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  value = input<any>();

  /**
   * The value that represents the 'OFF' state (only used if 'value' is set).
   */
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  offValue = input<any>();

  /**
   * Text to display when the toggle is 'ON'.
   */
  // eslint-disable-next-line @angular-eslint/no-input-rename
  cosToggleTextOn = input<string>('', { alias: 'textOn' });

  /**
   * Text to display when the toggle is 'OFF'.
   */
  // eslint-disable-next-line @angular-eslint/no-input-rename
  cosToggleTextOff = input<string>('', { alias: 'textOff' });

  disabled = input<boolean>(false);

  /**
   * Emits the new value after a toggle operation.
   */
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  toggleClick = output<any>();

  /**
   * Computes if the toggle is currently in the 'ON' state.
   */
  isEnabled = computed(() => {
    const m = this.modelValue();
    const v = this.value();

    if (v !== undefined) {
      return m === v;
    }
    return !!m;
  });

  /**
   * Performs the toggle action based on current state and input values.
   */
  toggle() {
    if (this.disabled()) return;
    const v = this.value();
    const offV = this.offValue();
    let nextValue: any;

    if (v !== undefined) {
      if (this.modelValue() === v && offV !== undefined) {
        nextValue = offV;
      } else {
        nextValue = v;
      }
    } else {
      nextValue = !this.modelValue();
    }

    this.modelValue.set(nextValue);
    this.toggleClick.emit(nextValue);
  }
}

import { vi, describe, it, expect, beforeEach } from 'vitest';
